from typing import Optional

from taf.rfrl.utilities.robot.RobotWrapper import RobotWrapper

from taf.rfrl.csv4all.resources.test_cases.exceptions import IterationFailedError, TestFailedOnTeardownError, \
    RecoveryAttemptFailedError
from taf.rfrl.csv4all.resources.test_cases.parallel_upgrade_test import ParallelUpgradeTest
from taf.rfrl.csv4all.resources.node.exceptions import WrongSwVersion
from taf.rfrl.csv4all.resources.node.node import Node
from taf.rfrl.csv4all.resources.utilities.decorators import method_decorator
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class ParallelUpgradeRollbackTest(ParallelUpgradeTest):

    def __init__(self, nodes_details, test_nodes_details, iterations_per_node, report,
                 calculate_kpi=True, kpi_targets: Optional[dict] = None,
                 use_dcap=False, qc_domain=None, qc_id=None, qc_project=None, customers_list=None,
                 report_comment=None, sw_build=None, topology=None, use_external_storage=False, download_path=None,
                 restore_to_target_sw=True, use_testpackage: Optional[bool] = False, stop_test_after_fail: bool = False,
                 artifactory_location: str = "espoo2", package_suffix: Optional[str] = "A54", l3_call_method=None,
                 synchronize_software_on_passive: bool = False, yaft_path: str = "/home/ute/YAFT",
                 virtualenv_dir: str = None, detailed_console_log: bool = True, ru_update_sw: bool = False,
                 collect_passed_logs: int = 0, diagnostic_check: bool = False):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, report,
                         calculate_kpi, kpi_targets, use_dcap, qc_domain, qc_id, qc_project, customers_list,
                         report_comment, sw_build, topology, use_external_storage, download_path, use_testpackage,
                         stop_test_after_fail, artifactory_location, package_suffix, l3_call_method,
                         synchronize_software_on_passive, yaft_path, virtualenv_dir, detailed_console_log, ru_update_sw,
                         collect_passed_logs=collect_passed_logs, diagnostic_check=diagnostic_check)
        self.restore_to_target_sw = restore_to_target_sw

    def parallel_test_operation(self):
        self.set_timestamp_reporting_and_kpi()
        self.software_update_test()
        self.software_rollback_test()
        return self.failed_nodes

    def software_rollback_test(self):
        with RobotWrapper("Software Rollback Test", "kw"):
            if self.check_parallel_nodes_state_before_rollback():
                self.failed_nodes.update(self.parallel_sw_rollback_operation())
            else:
                self.failed_nodes_during_rollback = {node.node_alias for node in self.test_nodes}
                self.failed_nodes.update({node.node_alias for node in self.test_nodes})
            self._log_operation_status("rollback", self.failed_nodes_during_rollback)

    @method_decorator()
    def check_parallel_nodes_state_before_rollback(self):
        try:
            active_sw = self.multi_runner.run_operations_as_threads_and_return(self.test_nodes,
                                                                               Node.verify_active_sw_version)
            if active_sw.get("Failed"):
                failed_nodes = {node for node in {*active_sw['Failed'].keys()}}
                raise WrongSwVersion(f"Integration Fialed for Nodes: {failed_nodes}")
        except Exception as e:
            test_logger(e, "ERROR")
            return False
        failed_nodes = self.precheck_method()
        if failed_nodes:
            self.gather_mumin_logs_and_snapshot(f"before_rollback")
            try:
                self.run_recovery_method(failed_nodes)
            except RecoveryAttemptFailedError:
                raise
            return False
        return True

    @method_decorator()
    def verify_active_sw_on_test_nodes(self, sw, rollback_on_fail: bool = False):
        for node in self.test_nodes:
            sw_build = getattr(node, sw)
            try:
                node.verify_active_sw_version(sw_build)
            except WrongSwVersion as sw_version:
                if rollback_on_fail:
                    node.perform_rollback_and_wait_for_reload()
                    node.verify_node_bts_state()
                raise sw_version

    def run_test_verification(self, node, hw_timer: int = None, alarm_timer: int = None):
        return self.failed_nodes_during_update

    @method_decorator()
    def parallel_sw_rollback_operation(self):
        operation = "rollback"
        self._set_reset_check_for_test_node(False)
        try:
            self.multi_runner.start_log_tracing_all_nodes()
            self.multi_runner.start_watching_alarms_on_all_nodes()
            self.gather_blackbox_and_set_reset_counter(operation)
            self.perform_parallel_sw_rollback()
            self.failed_nodes_during_rollback = self.verify_nodes_after_parallel_sw_change_operation(operation)
            if not self.failed_nodes_during_rollback and not self.passed_logs_gathered:
                self.gather_mumin_logs_and_snapshot(operation)
            return self.failed_nodes_during_rollback
        except Exception as e:
            return self.exception_handling_parallel(operation=operation, exception=e)
        finally:
            self.remove_allowed_alarms_from_nodes(self.nodes, self.all_allowed_specific_faults)
            self._set_reset_check_for_test_node(True)

    @method_decorator()
    def _set_reset_check_for_test_node(self, value: bool):
        for node in self.test_nodes:
            node.logsverify.reset_check = value

    @method_decorator()
    def perform_parallel_sw_rollback(self):
        self.add_allowing_alarms()
        self.perform_multi_node_sw_rollback()

    def perform_multi_node_sw_rollback(self):
        download_results = self.multi_runner.run_operations_as_threads_and_return(
            self.test_nodes, Node.perform_rollback_and_wait_for_reload)
        if download_results.get("Failed"):
            raise Exception("Multi node SW Rollback failed")

    def test(self):
        self.run_iteration_precondition()
        self.failed_nodes = self.parallel_test_operation()
        self.report_results_to_uuf_dashboard()
        self.run_parallel_iteration_postcondition()
        if self.failed_nodes:
            raise IterationFailedError(f"Iteration Failed. Issues detected on nodes : {self.failed_nodes}")
        if self.l3_call_method and not self.l3_call_result:
            raise IterationFailedError("Iteration Failed. L3 Call failed.")

    def run_parallel_iteration_postcondition(self):
        with RobotWrapper("Iteration Postcondition", "kw"):
            self.verify_active_sw_on_test_nodes("source_sw", rollback_on_fail=True)

    def test_teardown(self):
        self.current_logs_dir = f"{self.log_dir}/Test_Teardown"
        try:
            if self.restore_to_target_sw:
                self.setup_admin_connections()
                failed_nodes = self.parallel_update_sw_operation()
                if failed_nodes:
                    raise TestFailedOnTeardownError
        finally:
            if self.restore_to_target_sw:
                self.teardown_nodes()
            super().test_teardown()
